public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int n = S.length();

        // S = ABABA, |S| = 3*la + 2*lb
        // la >= 1, lb >= 1
        // So 3*la + 2*lb = n => lb = (n - 3*la) / 2

        String bestA = null, bestB = null;

        for (int la = 1; la * 3 + 2 <= n; la++) {
            int rem = n - 3 * la;
            if (rem <= 0) break;
            if (rem % 2 != 0) continue;
            int lb = rem / 2;
            if (lb < 1) continue;

            // Verify: S = A B A B A
            // positions: A=[0,la), B=[la,la+lb), A=[la+lb,2la+lb), B=[2la+lb,2la+2lb), A=[2la+2lb,3la+2lb)
            String A = S.substring(0, la);
            String B = S.substring(la, la + lb);

            int pos = 0;
            boolean valid = true;

            // Check first A
            if (!S.substring(pos, pos + la).equals(A)) valid = false;
            pos += la;
            // Check first B
            if (valid && !S.substring(pos, pos + lb).equals(B)) valid = false;
            pos += lb;
            // Check second A
            if (valid && !S.substring(pos, pos + la).equals(A)) valid = false;
            pos += la;
            // Check second B
            if (valid && !S.substring(pos, pos + lb).equals(B)) valid = false;
            pos += lb;
            // Check third A
            if (valid && !S.substring(pos, pos + la).equals(A)) valid = false;

            if (valid) {
                bestA = A;
                bestB = B;
                break; // smallest la first
            }
        }

        if (bestA != null) {
            System.out.println("Love " + bestA + bestB + "!");
        } else {
            System.out.println("mitomerarenaiWA");
        }
    }
}

