int main() {
    char s[100001];
    scanf("%s", s);
    int n = strlen(s);

    for (int lenA = 1; lenA <= n; lenA++) {
        int rem = n - 3 * lenA;
        if (rem <= 0 || rem % 2 != 0) continue;
        int lenB = rem / 2;

        // Check pattern: positions
        // A = s[0..lenA-1]
        // B = s[lenA..lenA+lenB-1]
        // A = s[lenA+lenB..2*lenA+lenB-1]
        // B = s[2*lenA+lenB..2*lenA+2*lenB-1]
        // A = s[2*lenA+2*lenB..3*lenA+2*lenB-1]

        int ok = 1;
        // Compare A parts
        for (int i = 0; i < lenA; i++) {
            if (s[i] != s[lenA + lenB + i] || s[i] != s[2*lenA + 2*lenB + i]) {
                ok = 0;
                break;
            }
        }
        if (!ok) continue;

        // Compare B parts
        for (int i = 0; i < lenB; i++) {
            if (s[lenA + i] != s[2*lenA + lenB + i]) {
                ok = 0;
                break;
            }
        }
        if (!ok) continue;

        // Found solution
        char A[100001], B[100001];
        strncpy(A, s, lenA);
        A[lenA] = '\0';
        strncpy(B, s + lenA, lenB);
        B[lenB] = '\0';
        printf("Love %s%s!\n", A, B);
        return 0;
    }

    printf("mitomerarenaiWA\n");
    return 0;
}

